import { connection } from "next/server";
import { Suspense } from "react";
import { staking } from "@/lib/contracts";
import { recentStakingEvents } from "@/lib/events";
import { stellar } from "@/lib/stellar";

const EVENT_COUNT = 20;

function reason(error: unknown): string {
  return (error instanceof Error && error.message) || String(error) || "unknown error";
}

async function TotalStaked() {
  await connection();
  try {
    const { result } = await staking().total_staked();
    return (
      <p>
        Total staked: <span data-testid="total-staked">{result.toString()}</span>
      </p>
    );
  } catch (error) {
    return <p data-testid="total-error">Could not read the total: {reason(error)}</p>;
  }
}

async function StakedBy({ address }: { address: string }) {
  await connection();
  try {
    const { result } = await staking().staked({ user: address });
    return (
      <p>
        Staked by <code>{address}</code>:{" "}
        <span data-testid="staked-amount">{result.toString()}</span>
      </p>
    );
  } catch (error) {
    return <p data-testid="staked-error">Could not read the stake for {address}: {reason(error)}</p>;
  }
}

async function Events() {
  await connection();
  try {
    const events = await recentStakingEvents(EVENT_COUNT);
    if (events.length === 0) return <p>No stake or unstake events yet.</p>;
    return (
      <ol>
        {events.map((event) => (
          <li
            key={event.id}
            data-testid="event"
            data-type={event.type}
            data-address={event.address}
            data-amount={event.amount.toString()}
          >
            {event.type} {event.amount.toString()} by <code>{event.address}</code> (ledger{" "}
            {event.ledger})
          </li>
        ))}
      </ol>
    );
  } catch (error) {
    return <p data-testid="events-error">Could not read events: {reason(error)}</p>;
  }
}

export default async function StakingPage({
  searchParams,
}: {
  searchParams: Promise<{ address?: string | string[] }>;
}) {
  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>
      </p>
      <Suspense fallback={<p>Reading the total…</p>}>
        <TotalStaked />
      </Suspense>
      <Suspense fallback={null}>
        <AddressStake searchParams={searchParams} />
      </Suspense>
      <h2>Recent activity</h2>
      <Suspense fallback={<p>Reading events…</p>}>
        <Events />
      </Suspense>
    </main>
  );
}

async function AddressStake({
  searchParams,
}: {
  searchParams: Promise<{ address?: string | string[] }>;
}) {
  const { address } = await searchParams;
  const first = Array.isArray(address) ? address[0] : address;
  if (!first) return null;
  return <StakedBy address={first} />;
}
